import type { Reserva, StatusReserva, StatusWhatsApp } from "@/store/useReservasStore";
import type { Esporte } from "@/lib/quadras";
import type { TipoReserva } from "@/lib/recorrencia/types";

export interface ReservaDbRow {
  id: string;
  user_id?: string | null;
  userId?: string | null;
  quadra_id?: string;
  quadraId?: string;
  nome_cliente?: string;
  nomeCliente?: string;
