1	import { supabase, isSupabaseConfigured } from "./client";
2	import { mascaraWhatsApp } from "@/lib/constants";
3	import type { UserProfile } from "./types";
4	
5	const STORAGE_CURRENT_USER_KEY = "reservei_current_user";
6	const STORAGE_MOCK_USERS_DB = "reservei_users_db";
7	
8	interface StoredUserRow {
9	  id: string;
10	  nome: string;
11	  telefone: string;
12	  senha?: string;
13	  data_nascimento?: string | null;
14	  criado_em?: string;
15	  bloqueado?: boolean;
16	  motivo_bloqueio?: string | null;
17	}
18	
19	function getLocalUsers(): StoredUserRow[] {
20	  if (typeof window === "undefined") return [];
21	  try {
22	    const raw = localStorage.getItem(STORAGE_MOCK_USERS_DB);
23	    if (!raw) return [];
24	    const list: StoredUserRow[] = JSON.parse(raw);
25	    const valid = list.filter(
26	      (u) => Boolean(u && u.id && u.telefone && u.telefone.replace(/\D/g, "").length >= 8)
27	    );
28	    if (valid.length !== list.length) {
29	      saveLocalUsers(valid);
30	    }
31	    return valid;
32	  } catch {
33	    return [];
34	  }
35	}
36	
37	function saveLocalUsers(users: StoredUserRow[]) {
38	  if (typeof window === "undefined") return;
39	  try {
40	    localStorage.setItem(STORAGE_MOCK_USERS_DB, JSON.stringify(users));
41	  } catch (err) {
42	    console.error("Erro ao salvar usuários locais:", err);
43	  }
44	}
45	
46	/**
47	 * Cria cadastro de usuário com Nome, Telefone (WhatsApp) e Senha.
48	 * Grava na tabela 'usuarios' do Supabase se disponível, com fallback local seguro.
49	 */
50	export async function cadastrarUsuarioSupabase(
51	  nome: string,
52	  telefone: string,
53	  senha: string,
54	  dataNascimento?: string
55	): Promise<{ user: UserProfile | null; error?: string }> {
56	  const digits = telefone.replace(/\D/g, "");
57	  const id = `usr_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
58	  const telefoneFormatado = mascaraWhatsApp(digits);
59	
60	  // 1. Tenta salvar na tabela 'usuarios' do Supabase
61	  if (isSupabaseConfigured()) {
62	    try {
63	      const { data, error } = await supabase
64	        .from("usuarios")
65	        .insert([
66	          {
67	            id,
68	            nome,
69	            telefone: digits,
70	            senha,
71	            data_nascimento: dataNascimento || null,
72	          },
73	        ])
74	        .select()
75	        .single();
76	
77	      if (error) {
78	        // Telefone duplicado
79	        if (error.code === "23505" || error.message.includes("duplicate") || error.message.includes("unique")) {
80	          return {
81	            user: null,
82	            error: "Este número de WhatsApp já possui uma conta cadastrada.",
83	          };
84	        }
85	        // Se a tabela 'usuarios' ainda não existe no Supabase, continua para o fallback
86	        console.warn(
87	          "[Auth] Tabela 'usuarios' ainda não configurada no Supabase. Utilizando armazenamento local sincronizado.",
88	          error.message
89	        );
90	      } else if (data) {
91	        const perfil: UserProfile = {
92	          id: data.id,
93	          nome: data.nome,
94	          telefone: mascaraWhatsApp(data.telefone),
95	          dataNascimento: data.data_nascimento,
96	          criadoEm: data.criado_em,
97	          bloqueado: data.bloqueado,
98	          motivo_bloqueio: data.motivo_bloqueio,
99	        };
100	
101	        if (typeof window !== "undefined") {
102	          localStorage.setItem(STORAGE_CURRENT_USER_KEY, JSON.stringify(perfil));
103	        }
104	
105	        return { user: perfil };
106	      }
107	    } catch (err) {
108	      console.warn("[Auth] Falha de conexão com Supabase:", err);
109	    }
110	  }
111	
112	  // 2. Fallback Local Storage (garante funcionamento imediato mesmo sem tabela no Supabase)
113	  const users = getLocalUsers();
114	  const existe = users.find((u) => u.telefone.replace(/\D/g, "") === digits);
115	  if (existe) {
116	    return {
117	      user: null,
118	      error: "Este número de WhatsApp já possui uma conta cadastrada.",
119	    };
120	  }
121	
122	  const novoUsuario: StoredUserRow = {
123	    id,
124	    nome,
125	    telefone: digits,
126	    senha,
127	    data_nascimento: dataNascimento || null,
128	    criado_em: new Date().toISOString(),
129	  };
130	
131	  users.push(novoUsuario);
132	  saveLocalUsers(users);
133	
134	  const perfil: UserProfile = {
135	    id: novoUsuario.id,
136	    nome: novoUsuario.nome,
137	    telefone: telefoneFormatado,
138	    dataNascimento: novoUsuario.data_nascimento,
139	    criadoEm: novoUsuario.criado_em,
140	          bloqueado: novoUsuario.bloqueado,
141	          motivo_bloqueio: novoUsuario.motivo_bloqueio,
142	  };
143	
144	  if (typeof window !== "undefined") {
145	    localStorage.setItem(STORAGE_CURRENT_USER_KEY, JSON.stringify(perfil));
146	  }
147	
148	  return { user: perfil };
149	}
150	
151	/**
152	 * Realiza login com WhatsApp e Senha
153	 */
154	export async function loginUsuarioSupabase(
155	  telefone: string,
156	  senha: string
157	): Promise<{ user: UserProfile | null; error?: string }> {
158	  const digits = telefone.replace(/\D/g, "");
159	
160	  // 1. Tenta autenticar na tabela 'usuarios' do Supabase
161	  if (isSupabaseConfigured()) {
162	    try {
163	      const { data, error } = await supabase
164	        .from("usuarios")
165	        .select("*")
166	        .eq("telefone", digits)
167	        .eq("senha", senha)
168	        .single();
169	
170	      if (!error && data) {
171	        const perfil: UserProfile = {
172	          id: data.id,
173	          nome: data.nome,
174	          telefone: mascaraWhatsApp(data.telefone),
175	          dataNascimento: data.data_nascimento,
176	          criadoEm: data.criado_em,
177	          bloqueado: data.bloqueado,
178	          motivo_bloqueio: data.motivo_bloqueio,
179	        };
180	
181	        if (typeof window !== "undefined") {
182	          localStorage.setItem(STORAGE_CURRENT_USER_KEY, JSON.stringify(perfil));
183	        }
184	
185	        return { user: perfil };
186	      }
187	    } catch (err) {
188	      console.warn("[Auth] Falha ao consultar Supabase:", err);
189	    }
190	  }
191	
192	  // 2. Fallback Local Storage
193	  const users = getLocalUsers();
194	  const encontrado = users.find(
195	    (u) => u.telefone.replace(/\D/g, "") === digits && u.senha === senha
196	  );
197	
198	  if (!encontrado) {
199	    return { user: null, error: "WhatsApp ou senha incorretos." };
200	  }
201	
202	  const perfil: UserProfile = {
203	    id: encontrado.id,
204	    nome: encontrado.nome,
205	    telefone: mascaraWhatsApp(encontrado.telefone),
206	    dataNascimento: encontrado.data_nascimento,
207	    criadoEm: encontrado.criado_em,
208	          bloqueado: encontrado.bloqueado,
209	          motivo_bloqueio: encontrado.motivo_bloqueio,
210	  };
211	
212	  if (typeof window !== "undefined") {
213	    localStorage.setItem(STORAGE_CURRENT_USER_KEY, JSON.stringify(perfil));
214	  }
215	
216	  return { user: perfil };
217	}
218	
219	/**
220	 * Obtém usuário logado atualmente (ou null)
221	 */
222	export async function obterUsuarioAtual(): Promise<UserProfile | null> {
223	  if (typeof window === "undefined") return null;
224	
225	  try {
226	    const raw = localStorage.getItem(STORAGE_CURRENT_USER_KEY);
227	    if (!raw) return null;
228	    let user: UserProfile = JSON.parse(raw);
229	
230	    // Consulta em tempo real com o Supabase se configurado
231	    if (isSupabaseConfigured() && user.id) {
232	      try {
233	        const { data } = await supabase
234	          .from("usuarios")
235	          .select("*")
236	          .eq("id", user.id)
237	          .maybeSingle();
238	
239	        if (data) {
240	          user = {
241	            id: data.id,
242	            nome: data.nome || user.nome,
243	            telefone: mascaraWhatsApp(data.telefone || user.telefone),
244	            dataNascimento: data.data_nascimento || user.dataNascimento,
245	            criadoEm: data.criado_em || user.criadoEm,
246	            bloqueado: data.bloqueado !== undefined ? Boolean(data.bloqueado) : user.bloqueado,
247	            motivo_bloqueio:
248	              data.motivo_bloqueio !== undefined ? data.motivo_bloqueio : user.motivo_bloqueio,
249	          };
250	          localStorage.setItem(STORAGE_CURRENT_USER_KEY, JSON.stringify(user));
251	        }
252	      } catch (err) {
253	        console.warn("[Auth] Erro ao sincronizar sessão com Supabase:", err);
254	      }
255	    }
256	
257	    return user;
258	  } catch {
259	    return null;
260	  }
261	}
262	
263	/**
264	 * Desconecta o usuário
265	 */
266	export async function logoutUsuarioSupabase(): Promise<void> {
267	  if (isSupabaseConfigured()) {
268	    try {
269	      await supabase.auth.signOut();
270	    } catch (err) {
271	      console.warn("[Auth] Erro ao deslogar do Supabase:", err);
272	    }
273	  }
274	
275	  if (typeof window !== "undefined") {
276	    try {
277	      localStorage.removeItem(STORAGE_CURRENT_USER_KEY);
278	      sessionStorage.removeItem(STORAGE_CURRENT_USER_KEY);
279	    } catch {}
280	  }
281	}
282	
283	/**
284	 * Atualiza os dados de perfil do usuário
285	 */
286	export async function atualizarPerfilSupabase(
287	  userId: string,
288	  dados: Partial<Omit<UserProfile, "id" | "criadoEm">>
289	): Promise<UserProfile | null> {
290	  const digits = dados.telefone ? dados.telefone.replace(/\D/g, "") : undefined;
291	
292	  // Atualiza no Supabase
293	  if (isSupabaseConfigured()) {
294	    try {
295	      await supabase
296	        .from("usuarios")
297	        .update({
298	          ...(dados.nome ? { nome: dados.nome } : {}),
299	          ...(digits ? { telefone: digits } : {}),
300	          ...(dados.dataNascimento !== undefined ? { data_nascimento: dados.dataNascimento } : {}),
301	          ...(dados.bloqueado !== undefined ? { bloqueado: dados.bloqueado } : {}),
302	          ...(dados.motivo_bloqueio !== undefined ? { motivo_bloqueio: dados.motivo_bloqueio } : {}),
303	        })
304	        .eq("id", userId);
305	    } catch (err) {
306	      console.warn("[Auth] Erro ao atualizar no Supabase:", err);
307	    }
308	  }
309	
310	  // Atualiza no LocalStorage
311	  if (typeof window !== "undefined") {
312	    try {
313	      // 1. Atualiza na base de usuários cadastrados locais
314	      const users = getLocalUsers();
315	      let index = users.findIndex((u) => u.id === userId);
316	      if (index === -1 && digits) {
317	        index = users.findIndex((u) => u.telefone.replace(/\D/g, "") === digits);
318	      }
319	      let updatedUser: UserProfile | null = null;
320	
321	      if (index >= 0) {
322	        users[index] = {
323	          ...users[index],
324	          ...(dados.nome ? { nome: dados.nome } : {}),
325	          ...(digits ? { telefone: digits } : {}),
326	          ...(dados.dataNascimento !== undefined ? { data_nascimento: dados.dataNascimento } : {}),
327	          ...(dados.bloqueado !== undefined ? { bloqueado: dados.bloqueado } : {}),
328	          ...(dados.motivo_bloqueio !== undefined ? { motivo_bloqueio: dados.motivo_bloqueio } : {}),
329	        };
330	        saveLocalUsers(users);
331	        updatedUser = {
332	          id: users[index].id,
333	          nome: users[index].nome,
334	          telefone: mascaraWhatsApp(users[index].telefone),
335	          dataNascimento: users[index].data_nascimento,
336	          criadoEm: users[index].criado_em,
337	          bloqueado: users[index].bloqueado,
338	          motivo_bloqueio: users[index].motivo_bloqueio,
339	        };
340	      } else {
341	        // Tenta recuperar os dados completos antes de salvar no armazenamento local
342	        let nomeRecuperado = dados.nome;
343	        let telRecuperado = digits;
344	        let nascimentoRecuperado = dados.dataNascimento;
345	        let criadoEmRecuperado = new Date().toISOString();
346	
347	        const rawCur = localStorage.getItem(STORAGE_CURRENT_USER_KEY);
348	        if (rawCur) {
349	          const cur: UserProfile = JSON.parse(rawCur);
350	          if (cur.id === userId) {
351	            nomeRecuperado = nomeRecuperado || cur.nome;
352	            telRecuperado = telRecuperado || cur.telefone.replace(/\D/g, "");
353	            nascimentoRecuperado =
354	              nascimentoRecuperado !== undefined ? nascimentoRecuperado : cur.dataNascimento;
355	            criadoEmRecuperado = cur.criadoEm || criadoEmRecuperado;
356	          }
357	        }
358	
359	        // Apenas salva no armazenamento local se houver um número de telefone válido
360	        if (telRecuperado && telRecuperado.length >= 8) {
361	          const novoLocal: StoredUserRow = {
362	            id: userId,
363	            nome: nomeRecuperado || "Cliente",
364	            telefone: telRecuperado,
365	            data_nascimento: nascimentoRecuperado || null,
366	            bloqueado: dados.bloqueado,
367	            motivo_bloqueio: dados.motivo_bloqueio,
368	            criado_em: criadoEmRecuperado,
369	          };
370	          users.push(novoLocal);
371	          saveLocalUsers(users);
372	          updatedUser = {
373	            id: novoLocal.id,
374	            nome: novoLocal.nome,
375	            telefone: mascaraWhatsApp(novoLocal.telefone),
376	            dataNascimento: novoLocal.data_nascimento,
377	            criadoEm: novoLocal.criado_em,
378	            bloqueado: novoLocal.bloqueado,
379	            motivo_bloqueio: novoLocal.motivo_bloqueio,
380	          };
381	        }
382	      }
383	
384	      // 2. Se for o usuário atualmente ativo na sessão, atualiza também a sessão ativa
385	      const raw = localStorage.getItem(STORAGE_CURRENT_USER_KEY);
386	      if (raw) {
387	        const current: UserProfile = JSON.parse(raw);
388	        const curDigits = current.telefone ? current.telefone.replace(/\D/g, "") : "";
389	        if (current.id === userId || (digits && curDigits === digits)) {
390	          const updatedSession: UserProfile = {
391	            ...current,
392	            ...(dados.nome ? { nome: dados.nome } : {}),
393	            ...(dados.telefone ? { telefone: mascaraWhatsApp(dados.telefone) } : {}),
394	            ...(dados.dataNascimento !== undefined ? { dataNascimento: dados.dataNascimento } : {}),
395	            ...(dados.bloqueado !== undefined ? { bloqueado: dados.bloqueado } : {}),
396	            ...(dados.motivo_bloqueio !== undefined ? { motivo_bloqueio: dados.motivo_bloqueio } : {}),
397	          };
398	          localStorage.setItem(STORAGE_CURRENT_USER_KEY, JSON.stringify(updatedSession));
399	          if (!updatedUser) updatedUser = updatedSession;
400	        }
401	      }
402	
403	      if (updatedUser) return updatedUser;
404	    } catch (err) {
405	      console.error("Erro ao atualizar usuário local:", err);
406	    }
407	  }
408	
409	  return null;
410	}
411	
412	/**
413	 * Exclui a conta do usuário permanentemente (LGPD)
414	 */
415	export async function excluirContaSupabase(userId: string): Promise<boolean> {
416	  if (isSupabaseConfigured()) {
417	    try {
418	      await supabase.from("usuarios").delete().eq("id", userId);
419	    } catch (err) {
420	      console.warn("[Auth] Erro ao deletar no Supabase:", err);
421	    }
422	  }
423	
424	  if (typeof window !== "undefined") {
425	    try {
426	      const raw = localStorage.getItem(STORAGE_CURRENT_USER_KEY);
427	      if (raw) {
428	        const cur: UserProfile = JSON.parse(raw);
429	        if (cur.id === userId) {
430	          localStorage.removeItem(STORAGE_CURRENT_USER_KEY);
431	        }
432	      }
433	      const users = getLocalUsers().filter((u) => u.id !== userId);
434	      saveLocalUsers(users);
435	    } catch {}
436	  }
437	
438	  return true;
439	}
440	
441	/**
442	 * Lista todos os usuários cadastrados (Supabase e armazenamento local sincronizado).
443	 */
444	export async function listarUsuariosCadastrados(): Promise<UserProfile[]> {
445	  const usersById = new Map<string, UserProfile>();
446	  const idByPhone = new Map<string, string>(); // digits -> id
447	
448	  // 1. Armazenamento Local
449	  if (typeof window !== "undefined") {
450	    try {
451	      const raw = localStorage.getItem(STORAGE_MOCK_USERS_DB);
452	      if (raw) {
453	        const list: StoredUserRow[] = JSON.parse(raw);
454	        // Filtra e limpa registros corrompidos ou sem telefone
455	        const validList = list.filter(
456	          (u) => Boolean(u && u.id && u.telefone && u.telefone.replace(/\D/g, "").length >= 8)
457	        );
458	        if (validList.length !== list.length) {
459	          saveLocalUsers(validList);
460	        }
461	
462	        for (const u of validList) {
463	          const digits = u.telefone.replace(/\D/g, "");
464	          const profile: UserProfile = {
465	            id: u.id,
466	            nome: u.nome,
467	            telefone: mascaraWhatsApp(u.telefone),
468	            dataNascimento: u.data_nascimento,
469	            criadoEm: u.criado_em,
470	            bloqueado: Boolean(u.bloqueado),
471	            motivo_bloqueio: u.motivo_bloqueio || null,
472	          };
473	          usersById.set(u.id, profile);
474	          if (digits) idByPhone.set(digits, u.id);
475	        }
476	      }
477	
478	      const rawCur = localStorage.getItem(STORAGE_CURRENT_USER_KEY);
479	      if (rawCur) {
480	        const cur: UserProfile = JSON.parse(rawCur);
481	        const digits = cur.telefone ? cur.telefone.replace(/\D/g, "") : "";
482	        if (digits && digits.length >= 8) {
483	          if (!usersById.has(cur.id) && !idByPhone.has(digits)) {
484	            usersById.set(cur.id, cur);
485	            idByPhone.set(digits, cur.id);
486	          }
487	        }
488	      }
489	    } catch {}
490	  }
491	
492	  // 2. Supabase
493	  if (isSupabaseConfigured()) {
494	    try {
495	      const { data, error } = await supabase.from("usuarios").select("*");
496	      if (!error && data) {
497	        for (const row of data) {
498	          const digits = String(row.telefone).replace(/\D/g, "");
499	          if (!digits || digits.length < 8) continue;
500	
501	          const existingId = idByPhone.get(digits) || row.id;
502	          const localMatch = usersById.get(existingId) || usersById.get(row.id);
503	
504	          const profile: UserProfile = {
505	            id: row.id,
506	            nome: row.nome || localMatch?.nome || "Cliente",
507	            telefone: mascaraWhatsApp(row.telefone || localMatch?.telefone || ""),
508	            dataNascimento: row.data_nascimento || localMatch?.dataNascimento,
509	            criadoEm: row.criado_em || localMatch?.criadoEm,
510	            bloqueado:
511	              row.bloqueado !== undefined && row.bloqueado !== null
512	                ? Boolean(row.bloqueado)
513	                : Boolean(localMatch?.bloqueado),
514	            motivo_bloqueio:
515	              row.motivo_bloqueio !== undefined && row.motivo_bloqueio !== null
516	                ? row.motivo_bloqueio
517	                : (localMatch?.motivo_bloqueio || null),
518	          };
519	
520	          if (existingId && existingId !== row.id) {
521	            usersById.delete(existingId);
522	          }
523	          usersById.set(row.id, profile);
524	          idByPhone.set(digits, row.id);
525	        }
526	      }
527	    } catch {}
528	  }
529	
530	  return Array.from(usersById.values());
531	}
