534	 * Retorna mapa síncrono de telefones cadastrados (apenas dígitos) -> userId
535	 * baseado no cache local atual.
536	 */
537	export function getTelefonesCadastradosLocal(): Map<string, string> {
538	  const map = new Map<string, string>();
539	  if (typeof window === "undefined") return map;
540	  try {
541	    const raw = localStorage.getItem(STORAGE_MOCK_USERS_DB);
542	    if (raw) {
