559	/**
560	 * Verifica se um telefone pertence a um usuário bloqueado
561	 */
562	export async function isTelefoneBloqueado(telefone: string): Promise<boolean> {
563	  const digits = telefone.replace(/\D/g, "");
564	  if (!digits || digits.length < 8) return false;
565	
566	  // 1. Tenta checar diretamente no Supabase em tempo real
567	  if (isSupabaseConfigured()) {
568	    try {
569	      const { data, error } = await supabase
570	        .from("usuarios")
571	        .select("bloqueado")
572	        .eq("telefone", digits)
573	        .maybeSingle();
574	
575	      if (!error && data && data.bloqueado !== undefined && data.bloqueado !== null) {
576	        return Boolean(data.bloqueado);
577	      }
578	    } catch {}
579	  }
580	
581	  // 2. Fallback sincronizado
582	  const todos = await listarUsuariosCadastrados();
583	  const encontrado = todos.find((u) => u.telefone.replace(/\D/g, "") === digits);
584	  return Boolean(encontrado?.bloqueado);
585	}
