602	      ...(dadosAtuais?.dataNascimento !== undefined ? { dataNascimento: dadosAtuais.dataNascimento } : {}),
603	    });
604	    return true;
605	  } catch (err) {
606	    console.error("Erro ao alterar bloqueio:", err);
607	    return false;
608	  }
