1	"use client";
2	
3	import { useEffect, useCallback } from "react";
4	import type { UserProfile } from "@/lib/supabase/types";
5	import {
6	  cadastrarUsuarioSupabase,
7	  loginUsuarioSupabase,
8	  obterUsuarioAtual,
9	  logoutUsuarioSupabase,
10	  atualizarPerfilSupabase,
11	  excluirContaSupabase,
12	} from "@/lib/supabase/authService";
13	import { supabase, isSupabaseConfigured } from "@/lib/supabase/client";
14	import { useAuthStore, getUsuarioCacheLocal } from "@/store/useAuthStore";
15	
16	/**
17	 * Hook de autenticação do usuário.
18	 *
19	 * Conectado à store global Zustand (`useAuthStore`) com hidratação síncrona
20	 * de cache local (`localStorage`), garantindo que:
21	 * 1. A sessão nunca se perca durante navegações de rota (ex.: ir para /minha-conta e voltar para /).
22	 * 2. Não ocorra flickering de botões de login/cadastro enquanto a sessão é revalidada em segundo plano.
23	 * 3. Qualquer alteração de perfil reflita simultaneamente em todos os componentes.
24	 */
25	export function useUserAuth() {
26	  const user = useAuthStore((s) => s.user);
27	  const loading = useAuthStore((s) => s.loading);
28	  const hasHydrated = useAuthStore((s) => s.hasHydrated);
29	  const setUser = useAuthStore((s) => s.setUser);
30	  const setLoading = useAuthStore((s) => s.setLoading);
31	  const setHasHydrated = useAuthStore((s) => s.setHasHydrated);
32	
33	  // Carrega e sincroniza usuário na inicialização
34	  useEffect(() => {
35	    let isMounted = true;
36	
37	    // Hidratação síncrona do cache local assim que o componente monta no cliente
38	    if (!hasHydrated && typeof window !== "undefined") {
39	      const cached = getUsuarioCacheLocal();
40	      if (cached && isMounted) {
41	        setUser(cached);
42	      }
43	      setHasHydrated(true);
44	    }
45	
46	    async function carregarSessao() {
47	      try {
48	        const u = await obterUsuarioAtual();
49	        if (u && u.id.startsWith("usr_demo_")) {
50	          await logoutUsuarioSupabase();
51	          if (isMounted) {
52	            setUser(null);
53	            setLoading(false);
54	          }
55	          return;
56	        }
57	        if (isMounted) {
58	          setUser(u);
59	          setLoading(false);
60	        }
61	      } catch {
62	        if (isMounted) setLoading(false);
63	      }
64	    }
65	
66	    void carregarSessao();
67	
68	    const handleSync = async () => {
69	      if (!isMounted) return;
70	      try {
71	        const u = await obterUsuarioAtual();
72	        if (isMounted) setUser(u);
73	      } catch {}
74	    };
75	
76	    if (typeof window !== "undefined") {
77	      window.addEventListener("storage", handleSync);
78	      window.addEventListener("focus", handleSync);
79	    }
80	
81	    // Inscrição para mudanças de autenticação no Supabase
82	    let authSub: { unsubscribe: () => void } | null = null;
83	    if (isSupabaseConfigured()) {
84	      const {
85	        data: { subscription },
86	      } = supabase.auth.onAuthStateChange(async (_event, session) => {
87	        if (!isMounted) return;
88	        const u = await obterUsuarioAtual();
89	        if (isMounted) setUser(u);
90	      });
91	      authSub = subscription;
92	    }
93	
94	    return () => {
95	      isMounted = false;
96	      if (typeof window !== "undefined") {
97	        window.removeEventListener("storage", handleSync);
98	        window.removeEventListener("focus", handleSync);
99	      }
100	      if (authSub) {
101	        authSub.unsubscribe();
102	      }
103	    };
104	  }, [setUser, setLoading]);
105	
106	  const login = useCallback(
107	    async (telefone: string, senha: string): Promise<{ success: boolean; error?: string }> => {
108	      setLoading(true);
109	      const res = await loginUsuarioSupabase(telefone, senha);
110	      setLoading(false);
111	      if (res.user) {
112	        setUser(res.user);
113	        return { success: true };
114	      }
115	      return { success: false, error: res.error || "Erro ao realizar login." };
116	    },
117	    [setUser, setLoading]
118	  );
119	
120	  const cadastrar = useCallback(
121	    async (
122	      nome: string,
123	      telefone: string,
124	      senha: string,
125	      dataNascimento?: string
126	    ): Promise<{ success: boolean; user?: UserProfile; error?: string }> => {
127	      setLoading(true);
128	      const res = await cadastrarUsuarioSupabase(nome, telefone, senha, dataNascimento);
129	      setLoading(false);
130	      if (res.user) {
131	        setUser(res.user);
132	        return { success: true, user: res.user };
133	      }
134	      return { success: false, error: res.error || "Erro ao cadastrar usuário." };
135	    },
136	    [setUser, setLoading]
137	  );
138	
139	  const logout = useCallback(async () => {
140	    setLoading(true);
141	    await logoutUsuarioSupabase();
142	    if (typeof window !== "undefined") {
143	      try {
144	        localStorage.removeItem("reservei_current_user");
145	        sessionStorage.removeItem("reservei_current_user");
146	      } catch {}
147	    }
148	    setUser(null);
149	    setLoading(false);
150	  }, [setUser, setLoading]);
151	
152	  const atualizarPerfil = useCallback(
153	    async (dados: Partial<Omit<UserProfile, "id" | "criadoEm">>): Promise<boolean> => {
154	      if (!user) return false;
155	      const updated = await atualizarPerfilSupabase(user.id, dados);
156	      if (updated) {
157	        setUser(updated);
158	        return true;
159	      }
160	      return false;
161	    },
162	    [user, setUser]
163	  );
164	
165	  const excluirConta = useCallback(async (): Promise<boolean> => {
166	    if (!user) return false;
167	    const ok = await excluirContaSupabase(user.id);
168	    if (ok) {
169	      setUser(null);
170	      return true;
171	    }
172	    return false;
173	  }, [user, setUser]);
174	
175	  return {
176	    user,
177	    loading,
178	    hasHydrated,
179	    isAutenticado: Boolean(user),
180	    login,
181	    cadastrar,
182	    logout,
183	    atualizarPerfil,
184	    excluirConta,
185	  };
186	}
