1	import { create } from "zustand";
2	import type { UserProfile } from "@/lib/supabase/types";
3	
4	export interface AuthState {
5	  /** Perfil do usuário atualmente autenticado ou null se visitante */
6	  user: UserProfile | null;
7	  /** Indica se a verificação inicial de autenticação está em andamento */
8	  loading: boolean;
9	  /** Indica se a primeira hidratação do cliente já foi concluída */
10	  hasHydrated: boolean;
11	  /** Atualiza o usuário autenticado na store global */
12	  setUser: (user: UserProfile | null) => void;
13	  /** Atualiza o estado de carregamento */
14	  setLoading: (loading: boolean) => void;
15	  /** Marca a conclusão da hidratação inicial do cliente */
16	  setHasHydrated: (hasHydrated: boolean) => void;
17	}
18	
19	/**
20	 * Lê o perfil do usuário do cache local (localStorage).
21	 */
22	export function getUsuarioCacheLocal(): UserProfile | null {
23	  if (typeof window === "undefined") return null;
24	  try {
25	    const raw = localStorage.getItem("reservei_current_user");
26	    if (!raw) return null;
27	    const parsed = JSON.parse(raw);
28	    if (parsed && typeof parsed === "object" && parsed.id && !parsed.id.startsWith("usr_demo_")) {
29	      return parsed as UserProfile;
30	    }
31	    return null;
32	  } catch {
33	    return null;
34	  }
35	}
36	
37	/**
38	 * Store global de autenticação baseada em Zustand.
39	 *
40	 * `user` inicia como null e `hasHydrated` como false para garantir
41	 * que o HTML gerado no servidor (SSR) seja idêntico ao primeiro frame
42	 * de renderização no cliente, prevenindo qualquer erro de hidratação do React/Next.js.
43	 *
44	 * Assim que o cliente monta, o cache do localStorage é hidratado e `hasHydrated`
45	 * torna-se true. Esse estado é preservado na memória global durante toda a navegação
46	 * client-side (SPA), eliminando flickering ou falsos deslogamentos entre rotas.
47	 */
48	export const useAuthStore = create<AuthState>((set) => ({
49	  user: null,
50	  loading: true,
51	  hasHydrated: false,
52	  setUser: (user) => set({ user, loading: false }),
53	  setLoading: (loading) => set({ loading }),
54	  setHasHydrated: (hasHydrated) => set({ hasHydrated }),
55	}));
