// Uso: node run2.mjs <schema_base.sql> <teste.sql> <migração...>
import { PGlite } from "@electric-sql/pglite";
import fs from "fs";
const [base, test, ...migs] = process.argv.slice(2);
const db = new PGlite();
await db.exec(`
CREATE SCHEMA auth;
CREATE TABLE auth.users (id uuid primary key, email text, raw_user_meta_data jsonb, is_anonymous boolean default false);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT COALESCE(NULLIF(current_setting('request.jwt.claim.sub', true), ''),
                  (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub'))::uuid $$;
CREATE ROLE anon; CREATE ROLE authenticated;
`);
const b = fs.readFileSync(base, "utf8");
const trecho = (ini, fim) => b.slice(b.indexOf(ini), b.indexOf(fim));
await db.exec(trecho("CREATE TABLE IF NOT EXISTS public.reservas (", "CREATE INDEX IF NOT EXISTS idx_reservas_data_quadra"));
await db.exec(trecho("CREATE TABLE IF NOT EXISTS public.usuarios (", "CREATE INDEX IF NOT EXISTS idx_usuarios_telefone"));
await db.exec(`INSERT INTO public.usuarios (id, nome, telefone, senha) VALUES ('usr_antigo', 'Antigo', '91900000000', '123');`);
for (const m of migs) {
  const sql = fs.readFileSync(m, "utf8");
  await db.exec(sql);
  await db.exec(sql);
}
console.log("usuarios antigos restantes:", (await db.query("select count(*)::int n from usuarios")).rows[0].n);
const t = fs.readFileSync(test, "utf8").split(/\r?\n/).filter((l) => !l.startsWith("\\")).join("\n");
try {
  await db.exec(t);
  console.log("teste ok");
} catch (e) {
  console.log("ERRO:", e.message, e.where);
  process.exit(1);
}

