// Uso: node run3.mjs <pasta migrations> <teste.sql> [arquivo de migração substituto]
// Aplica todas as migrações (duas vezes, para idempotência) num Postgres embutido
// com stubs mínimos de auth e storage, e roda o teste SQL.
import { PGlite } from "@electric-sql/pglite";
import fs from "fs";
import path from "path";
const [pasta, test, substituto] = process.argv.slice(2);
const db = new PGlite();
await db.exec(`
CREATE SCHEMA auth;
CREATE TABLE auth.users (id uuid primary key, email text, raw_user_meta_data jsonb, is_anonymous boolean default false);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT COALESCE(NULLIF(current_setting('request.jwt.claim.sub', true), ''),
                  (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub'))::uuid $$;
CREATE ROLE anon NOLOGIN; CREATE ROLE authenticated NOLOGIN;
CREATE SCHEMA storage;
CREATE TABLE storage.buckets (id text primary key, name text, public boolean);
CREATE TABLE storage.objects (id serial primary key, bucket_id text, name text);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
`);
const arquivos = fs.readdirSync(pasta).filter((f) => f.endsWith(".sql")).sort();
for (const f of arquivos) {
  const origem = substituto && path.basename(substituto).startsWith(f.slice(0, 14)) ? substituto : path.join(pasta, f);
  const sql = fs.readFileSync(origem, "utf8");
  try {
    await db.exec(sql);
    await db.exec(sql);
  } catch (e) {
    console.log("ERRO na migração", f, e.message);
    process.exit(1);
  }
}
await db.exec(`
GRANT USAGE ON SCHEMA public, auth TO anon, authenticated;
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated;
`);
const t = fs.readFileSync(test, "utf8").split(/\r?\n/).filter((l) => !l.startsWith("\\")).join("\n");
try {
  await db.exec(t);
  console.log("teste ok:", path.basename(test));
} catch (e) {
  console.log("ERRO:", e.message, "|", e.where);
  process.exit(1);
}

